// work.feed.list — generated by `pnpm gen:query work project-feed`. Read through ../repository.ts; RLS limits the
// rows to what the actor may see. Queries run read-only (02-architecture §3).
import { z } from 'zod';
import { defineQuery } from '../../kernel/index.ts';
import { workPermissions } from '../permissions.ts';

export const projectFeed = defineQuery({
  name: 'work.feed.list',
  permission: workPermissions.projectFeed,
  input: z.object({}),
  handle: () => Promise.resolve<{ id: string }[]>([]),
});
